//! How `DisassociateSourceGraphqlApi` refuses an `associationId` it cannot delete,
//! end to end over HTTP.
//!
//! One rule, asserted over a TABLE of association references rather than over the single
//! request that exposed it: the refusal is split on the SHAPE of the reference the
//! request carries, not on mere absence —
//!
//! * a value that is not a reference the service itself could have issued (an
//!   `associationId` is "the ID generated by the AppSync service for the source API
//!   association", which the service issues as a UUID, beside the opaque ids its own id
//!   counter mints) is a defect of the REQUEST — 400 `BadRequestException` whose message
//!   names the rejected value;
//! * a value of such a form which names no association of the Merged API addressed — one
//!   the service never issued, one it issued for another resource, or one it issued for
//!   this very association and has since removed — is a missing RESOURCE: 404
//!   `NotFoundException` with the fixed text that names no identifier.
//!
//! The rows differ along what the rule generalises over: the form of the reference (a
//! UUID, the service's own opaque id form, neither), the length of a reference of the
//! opaque form (one character short of the issued length, one past it, far shorter, far
//! longer), its alphabet (a digit outside the minted alphabet, uppercase, hyphens), and
//! its history (never issued, issued for another resource, issued for this association
//! and removed).
//!
//! The harness (`router`, `call`, `create_api`, `create_pair`, `get_path`) is the one the
//! association suites already carry, so every row drives the router the production
//! emulator mounts: routing, restJson1 (de)serialization, the handlers and the shared
//! engine together.

use std::time::Duration;

use serde_json::json;
use service_com_amazonaws_appsync_awsdeepdishcontrolplaneservice::state;
use smithy_server_runtime::MultiServiceRouter;

use crate::source_api_association::{call, create_api, create_pair, get_path, router, Api};

/// How long the row that must observe the far side of a scheduled deletion waits: the
/// service's own span plus slack. Only the TEST waits — the handler stores the due
/// instant.
const PAST_THE_DELETION: Duration = Duration::from_millis(250);

/// `AssociateSourceGraphqlApi`'s path, i.e. the association collection of a Merged API.
fn associations_of(merged_api_identifier: &str) -> String {
    format!("/v1/mergedApis/{merged_api_identifier}/sourceApiAssociations")
}

/// Which reference a row carries in the request's `associationId` path label.
#[derive(Debug, Clone, Copy)]
enum Reference {
    /// A value the row writes out itself.
    Literal(&'static str),
    /// The Merged API's own `apiId`: an id the service minted, so a reference of the
    /// shape it issues, but never one of an association.
    MergedApiId,
    /// The `associationId` the service minted for an association of this Merged API
    /// whose scheduled deletion the clock has since performed.
    RemovedAssociationId,
}

/// One row: the reference the request carries and which side of the split it falls on.
#[derive(Debug)]
struct Case {
    label: &'static str,
    reference: Reference,
    /// Whether the reference is one the service could never have issued, which is what
    /// makes the REQUEST malformed rather than the resource missing.
    malformed: bool,
}

/// The reference table.
///
/// The forms a reference can take are the UUID the AppSync service issues an
/// `associationId` in and the opaque id this service's own counter mints
/// (`state::API_ID_LEN` characters over `crate::source_api_association::ID_ALPHABET`:
/// RFC 4648 base-32, lowercased — `a`-`z` and `2`-`7`), so the malformed rows walk the
/// bounds of both: one character short of the opaque length, one character past, a digit
/// just outside the alphabet at either end (`1`, `8`), uppercase, a UUID with a
/// character too few, a UUID in uppercase, and shapes neither form takes at all (a
/// hyphenated caller-invented reference, a single character).
fn cases() -> Vec<Case> {
    vec![
        Case {
            label: "never issued, opaque form, letters only",
            reference: Reference::Literal("abcdefghijklmnopqrstuvwxyz"),
            malformed: false,
        },
        Case {
            label: "never issued, opaque form, with the alphabet's digits",
            reference: Reference::Literal("a2b3c4d5e6f7g2h3i4j5k6l7m2"),
            malformed: false,
        },
        Case {
            label: "never issued, the uuid form the service issues",
            reference: Reference::Literal("3f1b9c7e-5a24-4d8f-9b61-0c2e7d84af53"),
            malformed: false,
        },
        Case {
            label: "never issued, the all-zero uuid",
            reference: Reference::Literal("00000000-0000-0000-0000-000000000000"),
            malformed: false,
        },
        Case {
            label: "issued for another resource of this account",
            reference: Reference::MergedApiId,
            malformed: false,
        },
        Case {
            label: "issued for an association of this merged api and since removed",
            reference: Reference::RemovedAssociationId,
            malformed: false,
        },
        Case {
            label: "one character short of the issued opaque length",
            reference: Reference::Literal("abcdefghijklmnopqrstuvwxy"),
            malformed: true,
        },
        Case {
            label: "one character past the issued opaque length",
            reference: Reference::Literal("abcdefghijklmnopqrstuvwxyza"),
            malformed: true,
        },
        Case {
            label: "issued opaque length, digit below the alphabet",
            reference: Reference::Literal("abcdefghijklmnopqrstuvwxy1"),
            malformed: true,
        },
        Case {
            label: "issued opaque length, digit above the alphabet",
            reference: Reference::Literal("a234567a234567a234567a2348"),
            malformed: true,
        },
        Case {
            label: "issued opaque length, uppercase",
            reference: Reference::Literal("ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
            malformed: true,
        },
        Case {
            label: "a hyphenated reference a caller invented",
            reference: Reference::Literal("source-api-association-77"),
            malformed: true,
        },
        Case {
            label: "a uuid one character short",
            reference: Reference::Literal("3f1b9c7e-5a24-4d8f-9b61-0c2e7d84af5"),
            malformed: true,
        },
        Case {
            label: "a uuid in uppercase",
            reference: Reference::Literal("3F1B9C7E-5A24-4D8F-9B61-0C2E7D84AF53"),
            malformed: true,
        },
        Case {
            label: "a single character",
            reference: Reference::Literal("x"),
            malformed: true,
        },
    ]
}

/// Associate `source` with `merged` from the Merged API's side and answer the
/// `associationId` the service minted.
async fn associate(
    router: &MultiServiceRouter,
    label: &str,
    source: &Api,
    merged: &Api,
) -> String {
    let created = call(
        router,
        "POST",
        &associations_of(&merged.id),
        Some(json!({"sourceApiIdentifier": source.id})),
    )
    .await;
    assert_eq!(
        created.status, 200,
        "case {label:?}: expected the association to be created, got {} {:?}",
        created.status, created.body
    );
    created.body["sourceApiAssociation"]["associationId"]
        .as_str()
        .unwrap_or_default()
        .to_string()
}

#[tokio::test]
async fn a_disassociate_splits_its_refusal_on_the_shape_of_the_association_reference() {
    let router = router();
    // The Merged API every row addresses, holding one LIVE association that no row may
    // touch, so a refusal cannot be mistaken for a deletion.
    let (source, merged) = create_pair(&router, "reference-split").await;
    let live_association = associate(&router, "live association", &source, &merged).await;

    // The row that must carry a reference the service issued for an association of THIS
    // Merged API and has since removed: a second source API is associated, its deletion
    // is asked for, and the clock alone then performs it.
    let gone_source = create_api(
        &router,
        "reference-split-gone-source",
        state::GRAPHQL_API_TYPE,
    )
    .await;
    let removed_association = associate(&router, "removed association", &gone_source, &merged).await;
    let scheduled = call(
        &router,
        "DELETE",
        &get_path(&merged.id, &removed_association),
        None,
    )
    .await;
    assert_eq!(
        scheduled.status, 200,
        "case removed association: expected the deletion to be scheduled, got {} {:?}",
        scheduled.status, scheduled.body
    );
    tokio::time::sleep(state::DELETION_SPAN + PAST_THE_DELETION).await;

    for case in cases() {
        let reference = match case.reference {
            Reference::Literal(value) => value.to_string(),
            Reference::MergedApiId => merged.id.clone(),
            Reference::RemovedAssociationId => removed_association.clone(),
        };
        // The two answers the one rule gives, stated from the row's class alone.
        let (status, error_type, message) = if case.malformed {
            (
                400,
                "BadRequestException",
                state::invalid_association_id_message(&reference),
            )
        } else {
            (
                404,
                "NotFoundException",
                state::ASSOCIATION_NOT_FOUND_MESSAGE.to_string(),
            )
        };

        let answer = call(
            &router,
            "DELETE",
            &get_path(&merged.id, &reference),
            None,
        )
        .await;
        assert_eq!(
            (answer.status, answer.error_type.as_str()),
            (status, error_type),
            "case {:?} ({reference:?}): expected {status} {error_type}, got {} {} {:?}",
            case.label,
            answer.status,
            answer.error_type,
            answer.body
        );
        assert_eq!(
            answer.body["message"].as_str(),
            Some(message.as_str()),
            "case {:?} ({reference:?}): expected the message {message:?}, got {:?}",
            case.label,
            answer.body["message"]
        );
        // A malformed request names the value that was refused; a missing resource names
        // no identifier at all, which is what keeps the two answers apart.
        if case.malformed {
            assert!(
                answer.body["message"]
                    .as_str()
                    .is_some_and(|text| text.ends_with(reference.as_str())),
                "case {:?}: expected the refusal to end with the rejected reference \
                 {reference:?}, got {:?}",
                case.label,
                answer.body["message"]
            );
        } else {
            assert!(
                answer.body["message"]
                    .as_str()
                    .is_some_and(|text| !text.contains(reference.as_str())),
                "case {:?}: expected the not-found to name no identifier, got {:?}",
                case.label,
                answer.body["message"]
            );
        }
    }

    // Not one of the refused calls touched the Merged API's live association: it is still
    // readable, and still in the status its create left it in.
    let read = call(&router, "GET", &get_path(&merged.id, &live_association), None).await;
    assert_eq!(
        read.status, 200,
        "case live association: expected the untouched association to still be readable, got {} \
         {:?}",
        read.status, read.body
    );
    assert_eq!(
        read.body["sourceApiAssociation"]["associationId"].as_str(),
        Some(live_association.as_str()),
        "case live association: expected the addressed association back, got {:?}",
        read.body["sourceApiAssociation"]
    );
}

/// The shape test is the one the service's own minted ids satisfy, so a reference it
/// issued is never refused as malformed: every `associationId` the emulator answers an
/// associate with is recognizable, whatever the clock has since done to the association.
#[tokio::test]
async fn every_reference_the_service_issues_is_recognizable() {
    let router = router();
    let (source, merged) = create_pair(&router, "issued-references").await;

    // Several associations, so the assertion is over a set of minted references rather
    // than over one: each pair is associated once, so each row needs its own source API.
    let mut issued = vec![associate(&router, "issued 1", &source, &merged).await];
    for index in 2..=4 {
        let extra = create_api(
            &router,
            &format!("issued-references-source-{index}"),
            state::GRAPHQL_API_TYPE,
        )
        .await;
        issued.push(associate(&router, "issued n", &extra, &merged).await);
    }

    for reference in &issued {
        assert!(
            state::is_association_id(reference),
            "case issued {reference:?}: expected a minted associationId to be a recognizable \
             association reference, got {reference:?}"
        );
        let answer = call(&router, "DELETE", &get_path(&merged.id, reference), None).await;
        assert_eq!(
            answer.status, 200,
            "case issued {reference:?}: expected the deletion of a minted reference to be \
             scheduled, got {} {:?}",
            answer.status, answer.body
        );
    }

    // Past the due instant the references are gone from the store, and the SAME values
    // are then answered as a missing resource rather than as a malformed request.
    tokio::time::sleep(state::DELETION_SPAN + PAST_THE_DELETION).await;
    for reference in &issued {
        let answer = call(&router, "DELETE", &get_path(&merged.id, reference), None).await;
        assert_eq!(
            (answer.status, answer.error_type.as_str()),
            (404, "NotFoundException"),
            "case removed {reference:?}: expected 404 NotFoundException once the deletion came \
             due, got {} {} {:?}",
            answer.status,
            answer.error_type,
            answer.body
        );
        assert_eq!(
            answer.body["message"].as_str(),
            Some(state::ASSOCIATION_NOT_FOUND_MESSAGE),
            "case removed {reference:?}: expected the fixed not-found text, got {:?}",
            answer.body["message"]
        );
    }
}
